<script lang="ts">
 import {onMount} from 'svelte';import AdventureCard from '$lib/components/AdventureCard.svelte';import '$lib/platform/adventures.css';import {Layers,Plus,Upload,ArrowUpRight,ArrowRight,Search,Play,Pencil,MoreHorizontal,Package,Users,Globe2,FolderOpen,ChevronDown,X,Image as ImageIcon,Film} from 'lucide-svelte';import {request} from '$lib/platform/client';import {localAdventures,browserAdventures} from '$lib/storage/local-adventures';import {createAdventure,type Adventure} from '$lib/demo/adventure';import {office} from '$lib/demo/scenes';import {graphics} from '$lib/demo/pixelart';import {exportAdventure,unpackAdventure,importAdventure} from '$lib/storage/adventure-package';
 let {data}=$props();let adventures=$state<Adventure[]>([]),publications=$state<any[]>([]),usage=$state<any[]>([]),legacy=$state<Adventure[]>([]),name=$state('Nueva aventura'),message=$state(''),busy=$state(false),input:HTMLInputElement;let creating=$state(false),search=$state(''),filter=$state<'all'|'published'|'draft'>('all'),loading=$state(true),failed=$state(false);
 const publishedCount=$derived(publications.filter(p=>p.active).length);
 const filtered=$derived(adventures.filter(a=>a.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())&&(filter==='all'||(!!publications.find(p=>p.adventure_id===a.id)?.active)===(filter==='published'))));
 async function refresh(){const r=await request('/api/platform/adventures');adventures=r.adventures;publications=r.publications;usage=r.usage;}
 async function run(fn:()=>Promise<void>){if(busy)return;busy=true;message='';failed=false;try{await fn();await refresh();}catch(e){failed=true;message=(e as Error).message;}finally{busy=false;loading=false;}}
 async function create(){await run(async()=>{const a={...createAdventure([structuredClone(office)]),id:crypto.randomUUID(),name:name.trim()||'Nueva aventura'};await localAdventures.save(a,{pack:graphics,blobs:{}});location.href='/editor?adventure='+a.id;});}
 async function migrate(a:Adventure){await run(async()=>{const zip=await exportAdventure(a,browserAdventures),content=unpackAdventure(new Uint8Array(await zip.arrayBuffer()));content.adventure.id=crypto.randomUUID();await localAdventures.save(content.adventure,content);message='Copia incorporada a este espacio. El original local se conserva.';});}
 async function upload(e:Event){const target=e.currentTarget as HTMLInputElement,file=target.files?.[0];target.value='';if(file)await run(async()=>{await importAdventure(file);message='Aventura importada.';});}
 onMount(()=>{void run(refresh);});
</script>
<svelte:head><title>Mis aventuras — {data.principal?.tenant?.name??'Mi espacio'}</title></svelte:head>
<main class="adventures-page">
 <header class="gallery-masthead"><a class="gallery-brand" href="/admin"><span class="brand-icon"><Layers size={22}/></span>mi espacio</a><a class="gallery-link" href="/">Ver catálogo público <ArrowUpRight size={16}/></a></header>
 <div class="gallery-hero"><div><p class="gallery-kicker"><FolderOpen size={14}/> Espacio {data.principal?.tenant?.name??'personal'}</p><h1>Mis aventuras</h1><p class="intro">Crea, da forma a tus mundos y compártelos cuando estén listos.</p></div><button class="btn primary" onclick={()=>creating=!creating} aria-expanded={creating} aria-controls="create-adventure"><Plus size={17}/> Nueva aventura</button></div>
 <div class="studio-links"><a href="/library"><span class="tool-icon"><Package size={20}/></span><span><strong>Biblioteca del espacio</strong><small>Objetos, personajes y suelos</small></span><ArrowUpRight size={16}/></a><a href="/characters"><span class="tool-icon"><Users size={20}/></span><span><strong>Generador de personajes</strong><small>Dale vida a tu próximo protagonista</small></span><ArrowUpRight size={16}/></a></div>
 {#if creating}<form id="create-adventure" class="create-panel" onsubmit={e=>{e.preventDefault();void create();}}><label>Nombre de la aventura<input required maxlength="120" bind:value={name} placeholder="Ponle nombre a tu mundo"/></label><button class="btn primary" disabled={busy||!name.trim()}>Crear y editar <ArrowRight size={15}/></button><button class="btn" type="button" onclick={()=>creating=false} aria-label="Cerrar creación de aventura"><X size={16}/></button></form>{/if}
 {#if message}<p class:error={failed} class="gallery-notice" role={failed?'alert':'status'}>{message}</p>{/if}
 <h2 class="sr-only">Tus aventuras</h2><div class="gallery-toolbar"><div class="filters" aria-label="Filtrar aventuras"><button class:active={filter==='all'} aria-pressed={filter==='all'} onclick={()=>filter='all'}>Todas <span>{adventures.length}</span></button><button class:active={filter==='published'} aria-pressed={filter==='published'} onclick={()=>filter='published'}>Publicadas <span>{publishedCount}</span></button><button class:active={filter==='draft'} aria-pressed={filter==='draft'} onclick={()=>filter='draft'}>Borradores <span>{adventures.length-publishedCount}</span></button></div><div class="list-tools"><label class="gallery-search"><Search size={16}/><input aria-label="Buscar mis aventuras" placeholder="Buscar aventura…" bind:value={search}/></label><button class="btn import-button" disabled={busy} onclick={()=>input.click()}><Upload size={15}/> Importar ZIP</button></div></div>
 <input hidden type="file" accept=".zip" bind:this={input} onchange={upload}/>
 {#if loading}<div class="gallery-empty" role="status">Cargando tus aventuras…</div>{:else if filtered.length}<div class="adventure-grid">{#each filtered as a}{@const pub=publications.find(p=>p.adventure_id===a.id)}<AdventureCard title={a.name} eyebrow={data.principal?.tenant?.name??'Mi espacio'} status={pub?.active?'Publicada':'Borrador privado'} published={!!pub?.active} href={`/editor?adventure=${a.id}`} meta={`${a.maps.length} ${a.maps.length===1?'escenario':'escenarios'} · ${pub?.active?'Versión pública disponible':'Solo visible en tu espacio'}`}>
 <div class="button-row"><a class="btn primary grow" href={`/editor?adventure=${a.id}`}><Pencil size={14}/> Editar</a><a class="btn" href={`/preview?adventure=${a.id}`}><Play size={14}/> Probar</a><details class="card-menu"><summary aria-label={`Más opciones de ${a.name}`} title="Más opciones"><MoreHorizontal size={18}/></summary><div class="menu-items">{#if data.principal?.tenant?.permissions.publish}<button disabled={busy} onclick={()=>run(async()=>{await request('/api/platform/publish',{id:a.id,active:true});message='Publicada la versión guardada.';})}><Globe2 size={14}/>{pub?.active?'Actualizar publicación':'Publicar aventura'}</button>{#if pub?.active}<button class="withdraw" disabled={busy} onclick={()=>run(async()=>{await request('/api/platform/publish',{id:a.id,active:false});message='Publicación retirada. Tu aventura se conserva.';})}>Retirar publicación</button>{/if}{/if}<a href={`/sprites?adventure=${a.id}`}><Package size={14}/> Gestionar recursos</a>{#if pub?.active}<a href={`/play/${pub.slug}`}><ArrowUpRight size={14}/> Abrir versión pública</a>{/if}</div></details></div>
 <div class="card-bottom"><a href={`/sprites?adventure=${a.id}`}><Package size={13}/> Recursos</a>{#if pub?.active}<a href={`/play/${pub.slug}`}>Ver publicada <ArrowUpRight size={13}/></a>{/if}</div>
 </AdventureCard>{/each}</div>{:else}<div class="gallery-empty"><FolderOpen size={30}/><h3>{adventures.length?'No hay aventuras con este filtro':'Tu primer mundo empieza aquí'}</h3><p>{adventures.length?'Cambia el filtro o busca por otro nombre.':'Crea una aventura o importa un ZIP para empezar.'}</p>{#if !adventures.length}<button class="btn primary" onclick={()=>creating=true}><Plus size={15}/> Crear aventura</button>{/if}</div>{/if}
 <details class="workspace-details"><summary><span>Uso de tu espacio</span><span class="summary-note">{adventures.length} de {data.principal?.tenant?.limits.adventures} aventuras <ChevronDown size={15}/></span></summary><div class="usage-grid">{#each [{label:'Aventuras',value:adventures.length,max:data.principal?.tenant?.limits.adventures,icon:Layers},{label:'Publicadas',value:publishedCount,max:data.principal?.tenant?.limits.published,icon:Globe2},{label:'Imágenes / mes',value:usage.find(u=>u.kind==='images')?.used??0,max:data.principal?.tenant?.limits.images,icon:ImageIcon},{label:'Vídeos / mes',value:usage.find(u=>u.kind==='videos')?.used??0,max:data.principal?.tenant?.limits.videos,icon:Film}] as metric}<div class="metric"><span><metric.icon size={15}/>{metric.label}</span><strong>{metric.value} <small>/ {metric.max}</small></strong><progress value={metric.value} max={Math.max(1,metric.max??1)} aria-label={metric.label}></progress></div>{/each}</div><p class="detail-hint">Recursos guardados: hasta {data.principal?.tenant?.limits.storageMB} MB. Las solicitudes de IA reservadas cuentan como intentos, aunque fallen tras enviarse al proveedor.</p></details>
 <details class="workspace-details recovery"><summary><span>Recuperar aventuras de este navegador</span><ChevronDown size={15}/></summary><p class="detail-hint">Copia las aventuras de la versión anterior a tu espacio. Los originales se conservan.</p><button class="btn" disabled={busy} onclick={()=>run(async()=>{legacy=(await browserAdventures.load()).adventures;})}><FolderOpen size={15}/> Buscar copias locales</button>{#each legacy as a}<div class="legacy-item"><span>{a.name}</span><button class="btn" disabled={busy} onclick={()=>migrate(a)}>Copiar a este espacio</button></div>{/each}</details>
 <footer class="gallery-footer"><span><Layers size={14}/> Tus cambios se guardan en este espacio.</span><span>Publica para compartir una versión con los jugadores.</span></footer>
</main>
